/**
 * Repository integrity — the checkable form of "the TS version IS the project".
 *
 * The Python reference has been moved out and its working tree deleted (history kept in a
 * BACKUP.md), so these assertions pin the new shape:
 *
 *  - no Python source, config or requirement file anywhere in the tree;
 *  - the data the TS project needs is still here (fixtures, specs, replica
 *    inventories, the committed oracle artifacts, the MV3 extension);
 *  - the six cross-runtime parity harnesses and their frozen corpora are here
 *    (the corpora were GENERATED by the Python reference — they must not be
 *    regenerated from the implementation under test);
 *  - package scripts never reach for Python;
 *  - the public surface still exports the application layer.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import * as api from "../src/index.ts";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const SKIP_DIRS = new Set(["node_modules", ".git", "coverage", "dist"]);

function walk(dir: string, out: string[] = []): string[] {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (SKIP_DIRS.has(e.name)) continue;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, out);
    else out.push(path.relative(ROOT, p));
  }
  return out;
}

const FILES = walk(ROOT);
const exists = (rel: string): boolean => fs.existsSync(path.join(ROOT, rel));
const size = (rel: string): number => fs.statSync(path.join(ROOT, rel)).size;

describe("the repository is single-stack (TypeScript only)", () => {
  it("contains no Python source, config or requirement files", () => {
    const py = FILES.filter((f) => f.endsWith(".py") || f.endsWith(".pyi") || f.endsWith(".ipynb"));
    expect(py, `Python files still in the repo:\n${py.join("\n")}`).toEqual([]);
  });

  it("has no Python project scaffolding", () => {
    for (const f of ["requirements.txt", "pytest.ini", "setup.py", "pyproject.toml", "setup.cfg", "tox.ini"]) {
      expect(exists(f), `${f} is Python-era scaffolding`).toBe(false);
    }
  });

  it("has no Python cache directories", () => {
    const caches = FILES.filter((f) => f.includes("__pycache__") || f.includes(".pytest_cache"));
    expect(caches).toEqual([]);
  });

  it("keeps a TypeScript project at the root (not in a sub-directory)", () => {
    for (const f of ["package.json", "tsconfig.json", "src/index.ts", "tests", "tools"]) {
      expect(exists(f), `missing ${f}`).toBe(true);
    }
    expect(exists("ts")).toBe(false);
  });

  it("package scripts never call Python", () => {
    const pkg = JSON.parse(fs.readFileSync(path.join(ROOT, "package.json"), "utf-8")) as {
      scripts: Record<string, string>;
    };
    for (const [name, cmd] of Object.entries(pkg.scripts)) {
      expect(cmd, `script ${name} still shells out to Python`).not.toMatch(/python|pytest|uvicorn/);
    }
    for (const s of ["typecheck", "test", "test:parity", "verify", "bench", "apps", "apps:matrix", "plan-cli"]) {
      expect(Object.keys(pkg.scripts), `missing script ${s}`).toContain(s);
    }
  });
});

describe("the data the project needs is still here", () => {
  it.each([
    ["testpages/product.html", "fixture page"],
    ["testpages/attack.html", "injection fixture"],
    ["testpages/net_portal.html", "IP-config fixture"],
    ["testpages/camera_a.html", "camera fixture"],
    ["bench/cases.json", "the frozen-plan matrix"],
    ["bench/cases-live-long.json", "the long-flow live pack"],
    ["apps/README.md", "how to add an app pack"],
    ["apps/demo-app/pack.json", "the reference app pack (roles + journey + invariants)"],
    ["apps/cli-report/pack.json", "the tool-step pack (dry-run + confirm + retries)"],
    ["apps/repo-report/pack.json", "the real-tool pack (git + jq)"],
    ["apps/demo-tool/sources/demo-tool.json", "the CI-safe CLI tool source"],
    ["apps/git-log/sources/git-log.json", "a real CLI (git) source"],
    ["bench/fixtures/shop_home.html", "offline bench fixture"],
    ["camera_ips.xlsx", "the IP plan sheet"],
    ["devices.xlsx", "the camera sheet"],
    ["ctrip/sources/ctrip-flights-h5.json", "a config-driven data source"],
    ["ctrip/sources/ctrip-hotels-pc.json", "the second source on the same engine"],
    ["transfer/specs/ctrip.json", "the flow spec"],
    ["transfer/specs/skybook.json", "a replica spec"],
    ["extension/manifest.json", "the MV3 extension"],
    ["extension/background.js", "the extension service worker"],
    ["extension/content.js", "the extension content script"],
    ["qunar/results/QUNAR_RESULT.md", "the recorded qunar boundary"],
  ])("%s exists (%s)", (rel) => {
    expect(exists(rel)).toBe(true);
  });

  it("keeps every committed replica inventory and the byte-parity target", () => {
    const targets = ["ctrip/site/ctrip_data.js"];
    for (let n = 2; n <= 7; n++) targets.push(`transfer/site${n}/data${n}.js`);
    for (const t of targets) {
      expect(exists(t), `missing parity target ${t}`).toBe(true);
      expect(size(t), `${t} looks empty`).toBeGreaterThan(1000);
    }
  });
});

describe("the cross-runtime parity harnesses survived the move", () => {
  it.each([
    ["tools/parity.ts", "tools/parity-corpus.json"],
    ["tools/extraction-parity.ts", "tools/extraction-python.json"],
    ["tools/executor-parity.ts", "tools/executor-python.json"],
    ["tools/datasource-parity.ts", "tools/datasource-corpus.json"],
    ["tools/ctrip-parity.ts", "tools/ctrip-corpus.json"],
    ["tools/transfer-parity.ts", "tools/transfer-corpus.json"],
  ])("%s with its frozen corpus %s", (tool, corpus) => {
    expect(exists(tool), `missing ${tool}`).toBe(true);
    expect(exists(corpus), `missing ${corpus}`).toBe(true);
    expect(size(corpus), `${corpus} is empty`).toBeGreaterThan(100);
  });

  it("does not ship the Python generators (they belonged to the removed reference)", () => {
    const gens = FILES.filter((f) => /(^|\/)(gen|dump)_.*\.py$/.test(f));
    expect(gens, "generator scripts belonged to the removed Python reference (see BACKUP.md)").toEqual([]);
  });

  it("every parity tool reads a corpus that is committed, not generated at run time", () => {
    for (const tool of FILES.filter((f) => f.startsWith("tools/") && f.endsWith("-parity.ts"))) {
      const src = fs.readFileSync(path.join(ROOT, tool), "utf-8");
      expect(src, `${tool} still spawns a generator`).not.toMatch(/spawnSync\(\s*"python/);
      expect(src, `${tool} must read a committed corpus`).toMatch(/readFileSync\(/);
    }
  });
});

describe("the record of the Python reference is kept, not lost", () => {
  it("documents the backup and the measured design rules", () => {
    for (const f of ["README.md", "BACKUP.md", "CLAUDE.md", "ARCHITECTURE.md"]) {
      expect(exists(f), `missing ${f}`).toBe(true);
    }
    const readme = fs.readFileSync(path.join(ROOT, "README.md"), "utf-8");
    expect(readme).toMatch(/TypeScript|TS/);
    const backup = fs.readFileSync(path.join(ROOT, "BACKUP.md"), "utf-8");
    expect(backup).toMatch(/LayaWebUse-python-reference-backup/);
  });
});

describe("public surface (the layaapp/__init__ twin)", () => {
  it("exports the application layer", () => {
    for (const name of [
      "BrowserMiddleware", "browserSession", "TaskPlan", "PlanningRules", "checkSignal",
      "runPlan", "runSubgoalWithRetries", "LLMPlanner", "ScriptedPlanner",
      "extractElements", "hintLookup", "criteriaView", "esig", "firstIfSame", "extractSlots",
      "navRule", "affordanceRule", "hintMatch", "MockAuditor", "getAuditor",
      "QuickActionPicker", "createLayaOnnxRuntime", "installLayaRuntime",
      "loadSpec", "deriveSubgoals", "migrationMetrics", "snapshotText",
      "main", "BenchMiddleware", "buildPlan", "settingsUrl",
    ]) {
      expect(api, `missing export: ${name}`).toHaveProperty(name);
    }
    expect(typeof api.datasource.runSource).toBe("function");
    expect(typeof api.datasource.main).toBe("function");
    expect(api.main).not.toBe(api.datasource.main);
  });
});
